int lfd = socket(AF_INET, SOCK_STREAM, 0);
bind(lfd, ...); listen(lfd, backlog);
for (;;) {
    int cfd = accept4(lfd, NULL, NULL, SOCK_NONBLOCK | SOCK_CLOEXEC); /* Linux; use accept()+fcntl() portably */
    if (cfd < 0) { if (errno == EINTR) continue; if (errno == EAGAIN || errno == EWOULDBLOCK) continue; /* handle fatal error */ }
    else handler_activate(handler_create(service_id(cfd)), cfd);
}   /* connector side: connect(fd, ...), completion via poll + SO_ERROR */
